def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_m, last_o = history[-1]

    opp_c = 0
    my_d = 0
    for pair in history:
        if pair[1] == 'C':
            opp_c += 1
        if pair[0] == 'D':
            my_d += 1

    if opp_c == n:
        return 'D'

    if opp_c == 0:
        if n >= 5:
            return 'D'
        return 'C'

    if my_d == 0 and n >= 8 and last_m == 'C' and last_o == 'C' and opp_c * 2 >= n:
        return 'D'

    trans_d_total = 0
    trans_d_c = 0
    recent_start = n - 16
    if recent_start < 0:
        recent_start = 0
    recent_d_total = 0
    recent_d_c = 0

    for i in range(n - 1):
        mi = history[i][0]
        next_opp = history[i + 1][1]
        if mi == 'D':
            trans_d_total += 1
            if next_opp == 'C':
                trans_d_c += 1
            if i >= recent_start:
                recent_d_total += 1
                if next_opp == 'C':
                    recent_d_c += 1

    opp_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_d_streak += 1
        i -= 1

    mutual_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D' and history[i][1] == 'D':
        mutual_d_streak += 1
        i -= 1

    c_in_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        if history[i][0] == 'C':
            c_in_d_streak += 1
        i -= 1

    if last_m == 'D' and last_o == 'C' and opp_c * 4 >= n:
        return 'D'

    nonretaliatory = False
    if recent_d_total >= 2 and 20 * (recent_d_c + 1) >= 11 * (recent_d_total + 2) and opp_c * 2 >= n:
        nonretaliatory = True
    if trans_d_total >= 4 and 20 * (trans_d_c + 1) >= 11 * (trans_d_total + 2) and opp_c * 2 >= n:
        nonretaliatory = True

    if nonretaliatory:
        return 'D'

    if n >= 6:
        changes = 0
        for i in range(1, n):
            if history[i][1] != history[i - 1][1]:
                changes += 1
        if changes >= n - 2:
            return 'D'

    if last_o == 'D':
        if opp_c * 10 >= n * 25 and c_in_d_streak < 3:
            return 'C'
        return 'D'

    if opp_c * 3 <= n:
        return 'D'

    return 'C'
